create temporary table lolita_quote_scope on commit drop as select 'books'::text target,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(r)::text) h from public.books r where r.id<>'lolita') rows union all select 'sources'::text target,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(r)::text) h from public.sources r where r.book_id<>'lolita') rows union all select 'excerpts'::text target,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(r)::text) h from public.excerpts r where r.book_id<>'lolita') rows union all select 'unlocated_settings'::text target,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(r)::text) h from public.unlocated_settings r where r.book_id<>'lolita') rows union all select 'content_translations'::text target,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(r)::text) h from public.content_translations r where r.book_id<>'lolita') rows;
create temporary table lolita_quote_rows on commit drop as select x.*,E'{"language":"en","type":"original","highlightMode":"explicit","verificationStatus":"verified","quotationStatus":"reviewed-critical-use","analysisStatus":"native-pdf-evidence-reviewed","sourceEdition":"identified-digital-copy-imprint-not-stated","sourcePdfSha256":"9950fc89e4a03b5ade99076aa29c70be416fe8e8b8348086ec80b2b84794e7ee"}'::jsonb||jsonb_build_object('quote',x.quote,'attribution','Vladimir Nabokov · Lolita · '||case when original_section='foreword' then 'Foreword' else 'Part '||split_part(original_section,'.',1)||' · Chapter '||split_part(original_section,'.',2) end||' · digital copy, publisher and date not stated · PDF p. '||(select string_agg(value,', ' order by ordinal) from jsonb_array_elements_text(x.pages) with ordinality as p(value,ordinal))||case when context then ' · setting identified from chapter context' else '' end,'highlightTerms',x.terms,'sourcePdfPages',x.pages,'narrativeCategory',x.category,'contextEstablished',x.context,'verificationNote',coalesce(x.rationale,E'Conservative mentioned classification: this geographical reference is not used to establish an enacted scene here. Plans, biographies, catalogue entries, similes and reported information remain distinct from scenes. See the section-specific narrative notes.')) passage from jsonb_to_recordset(E'[{"section":1,"original_section":"foreword","place_id":"district-of-columbia","quote":"[…] and relation, Clarence Choate Clark, Esq., now of the District of Columbia bar, in asking me to edit the manuscript, based his […]","pages":[1],"terms":["District of Columbia"],"category":"mentioned","context":false,"reference_id":"1:core:district-of-columbia"},{"section":1,"original_section":"foreword","place_id":"paris","quote":"[…] a college sophomore, \\"Mona Dahl\\" is a student in Paris. […]","pages":[1],"terms":["Paris"],"category":"mentioned","context":false,"reference_id":"1:core:paris"},{"section":1,"original_section":"foreword","place_id":"florida","quote":"[…] has recently married the proprietor of a hotel in Florida. […]","pages":[1],"terms":["Florida"],"category":"mentioned","context":false,"reference_id":"1:core:florida"},{"section":1,"original_section":"foreword","place_id":"regional-ramsdale","quote":"[…] may be given as received from Mr. \\"Windmuller,\\" or \\"Ramsdale,\\" who desires his identity suppressed so that \\"the long shadow […]","pages":[1],"terms":["Ramsdale"],"category":"mentioned","context":false,"ordinal":0,"name":"Ramsdale"},{"section":1,"original_section":"foreword","place_id":"regional-gray-star","quote":"[…] to a stillborn girl, on Christmas Day 1952, in Gray Star, a settlemen in the remotest Northwest. […]","pages":[1],"terms":["Gray Star"],"category":"mentioned","context":false,"ordinal":1,"name":"Gray Star"},{"section":1,"original_section":"foreword","place_id":"regional-widworth","quote":"[…] John Ray, Jr., Ph.D. Widworth, Mass","pages":[3],"terms":["Widworth"],"category":"mentioned","context":false,"ordinal":3,"name":"Widworth"},{"section":1,"original_section":"foreword","place_id":"Northwest","quote":"[…] 1952, in Gray Star, a settlemen in the remotest Northwest. […]","pages":[1],"terms":["Northwest"],"category":"mentioned","context":false,"ordinal":2,"name":"Northwest"},{"section":3,"original_section":"1.2","place_id":"paris","quote":"I was born in 1910, in Paris. […]","pages":[3],"terms":["Paris"],"category":"mentioned","context":false,"reference_id":"3:core:paris"},{"section":3,"original_section":"1.2","place_id":"dorset","quote":"[…] of Jerome Dunn, the alpinist, and granddaughter of two Dorset parsons, experts in obscure subjects--paleopedology and Aeolian harps, respectively. […]","pages":[4],"terms":["Dorset"],"category":"mentioned","context":false,"reference_id":"3:core:dorset"},{"section":3,"original_section":"1.2","place_id":"pisa","quote":"[…] on their canes listed towards me like towers of Pisa. […]","pages":[5],"terms":["Pisa"],"category":"mentioned","context":false,"reference_id":"3:core:pisa"},{"section":3,"original_section":"1.2","place_id":"lyon","quote":"[…] in the autumn of 1923, to a lycie in Lyon (where we were to spend three winters); but alas, in […]","pages":[5],"terms":["Lyon"],"category":"mentioned","context":false,"reference_id":"3:core:lyon"},{"section":3,"original_section":"1.2","place_id":"italy","quote":"[…] in the summer of that year, he was touring Italy with Mme de R. […]","pages":[5],"terms":["Italy"],"category":"mentioned","context":false,"reference_id":"3:core:italy"},{"section":3,"original_section":"1.2","place_id":"regional-riviera","quote":"[…] minute some lovely, glossyblue picture-postcards. He owned a luxurious hotel on the Riviera. His father and two grandfathers had sold wine, jewels and silk, respectively. […] saw my little Annabel) were: a solemn, decorous and purely theoretical talk about pubertal surprises in the rose garden of the school with an […]","pages":[3,4,5],"terms":["Riviera"],"category":"action","context":false,"rationale":"Il dialogo nel giardino scolastico è un ricordo ambientato vicino al Mirana; il contesto della Riviera proviene dallo stesso capitolo.","region_index":16},{"section":3,"original_section":"1.2","place_id":"Danube","quote":"[…] French and Austrian descent, with a dash of the Danube in his veins. […]","pages":[3],"terms":["Danube"],"category":"mentioned","context":false,"ordinal":0,"name":"Danube"},{"section":3,"original_section":"1.2","place_id":"America","quote":"[…] traveler in perfumes, spent most of his time in America, where eventually he founded a firm and acquired a bit […]","pages":[5],"terms":["America"],"category":"mentioned","context":false,"ordinal":1,"name":"America"},{"section":4,"original_section":"1.3","place_id":"corfu","quote":"[…] and four months later she died of typhus in Corfu.","pages":[7],"terms":["Corfu"],"category":"mentioned","context":false,"reference_id":"4:core:corfu"},{"section":4,"original_section":"1.3","place_id":"regional-riviera","quote":"[…] chance, and nothing really mattered) we escaped from the cafe to the beach, and found a desolate stretch of sand, and there, […]","pages":[7],"terms":["beach"],"category":"action","context":true,"rationale":"La spiaggia è raggiunta dal caffè presso la villa vicina al Mirana: azioni e dialoghi del ricordo, non sola residenza.","region_index":16},{"section":5,"original_section":"1.4","place_id":"regional-riviera","quote":"[…] In a nervous and slenderleaved mimosa grove at the back of their villa we found a perch on the […]","pages":[8],"terms":["mimosa grove"],"category":"action","context":true,"rationale":"L’incontro notturno nel giardino continua l’ambientazione della villa e della Riviera nei due capitoli precedenti.","region_index":16},{"section":6,"original_section":"1.5","place_id":"paris","quote":"[…] While a college student, in London and Paris, paid ladies sufficed me. […]","pages":[9],"terms":["Paris"],"category":"mentioned","context":false,"reference_id":"6:core:paris"},{"section":6,"original_section":"1.5","place_id":"london","quote":"[…] While a college student, in London and Paris, paid ladies sufficed me. […]","pages":[9],"terms":["London"],"category":"mentioned","context":false,"reference_id":"6:core:london"},{"section":6,"original_section":"1.5","place_id":"deux-magots","quote":"[…] I sat with uranists in the Deux Magots. […]","pages":[9],"terms":["Deux Magots"],"category":"mentioned","context":false,"reference_id":"6:core:deux-magots"},{"section":6,"original_section":"1.5","place_id":"auteuil","quote":"[…] a job--teaching English to a group of adults in Auteuil. […]","pages":[10],"terms":["Auteuil"],"category":"mentioned","context":false,"reference_id":"6:core:auteuil"},{"section":6,"original_section":"1.5","place_id":"england","quote":"[…] Let me remind my reader that in England, with the passage of the Children and Young Person Act […]","pages":[13],"terms":["England"],"category":"mentioned","context":false,